<script>
 import {deduplicate} from '@adam/editor/diagnostics/messages.js';
 export let messages=[];export let navigate;export let canNavigate=()=>true;export let rail=false;export let embedded=false;
 let open=false,seen='',selectedId='',height=320,resizing=false,startY=0,startHeight=0;
 const labels={error:'Fehler',warning:'Warnungen',info:'Informationen'};
 $: items=deduplicate(messages);
 $: signature=JSON.stringify(items.filter(message=>message.severity==='error').map(message=>message.id));
 $: if(signature!==seen){if(items.some(message=>message.severity==='error'))open=true;seen=signature;selectedId=items[0]?.id??'';}
 $: if(!items.some(message=>message.id===selectedId))selectedId=items[0]?.id??'';
 $: selected=items.find(message=>message.id===selectedId);
 $: counts=Object.fromEntries(Object.keys(labels).map(level=>[level,items.filter(message=>message.severity===level).length]));
 $: if(embedded&&items.length)open=true;
 function select(id){selectedId=id;}
 function firstLine(value){return String(value??'').replace(/\s+/g,' ').trim();}
 function resizeStart(event){if(event.button!==0)return;resizing=true;startY=event.clientY;startHeight=height;event.currentTarget.setPointerCapture?.(event.pointerId);event.preventDefault();}
 function resizeMove(event){if(!resizing)return;height=Math.max(180,Math.min(Math.round(window.innerHeight*.8),startHeight+startY-event.clientY));}
 function resizeEnd(){resizing=false;}
</script>
<svelte:window on:pointermove={resizeMove} on:pointerup={resizeEnd} on:pointercancel={resizeEnd}/>
{#if items.length}{#if rail}<button class="rail-trigger" aria-label="Fehlerkonsole" title="Fehlerkonsole" aria-expanded={open} on:click={()=>open=!open}>!{counts.error||counts.warning||counts.info}</button>{/if}{#if !rail||open}<section class="diagnostics" class:open class:rail class:embedded style={`--diagnostic-height:${height}px`} aria-label="Fehlerkonsole">
 <div class="resize-handle" role="separator" aria-orientation="horizontal" aria-label="Höhe der Fehlerkonsole anpassen" on:pointerdown={resizeStart}></div>
 {#if !rail&&!embedded}<button class="summary" aria-expanded={open} on:click={()=>open=!open}><span>{open?'⌄':'⌃'} Fehlerkonsole</span><span>{counts.error} Fehler · {counts.warning} Warnungen · {counts.info} Informationen</span></button>{/if}
 {#if rail||open}<div class="content"><div class="table-wrap"><table><thead><tr><th></th><th>Schwere</th><th>Graph</th><th>Meldung</th></tr></thead><tbody>{#each items as message (message.id)}<tr class:selected={selectedId===message.id} data-severity={message.severity}>
 <td><button class="expand" aria-label={selectedId===message.id?'Details einklappen':'Details anzeigen'} aria-expanded={selectedId===message.id} on:click={()=>select(message.id)}>{selectedId===message.id?'⌄':'›'}</button></td>
 <td>{labels[message.severity]??message.severity}</td><td title={message.location??''}>{message.location??'—'}</td><td title={`${message.title}: ${message.description??''}`}><button class="message" on:click={()=>select(message.id)}><strong>{message.title}</strong>{#if message.description}<span> · {firstLine(message.description)}</span>{/if}</button></td>
 </tr>{/each}</tbody></table></div><aside class="details" aria-label="Fehlerdetails">{#if selected}<header><strong>Details</strong><span>{labels[selected.severity]??selected.severity}</span></header><div class="details-content"><h3>{selected.title}</h3><p>{selected.description}</p>{#if selected.cause}<p><b>Ursache:</b> {selected.cause}</p>{/if}{#if selected.hint}<p>{selected.hint}</p>{/if}{#if navigate&&selected.target&&canNavigate(selected.target)}<button on:click={()=>navigate(selected.target)}>Zum Graphen</button>{/if}<section class="preview-slot" aria-label="Vorschau"><strong>Vorschau</strong><p>Dieser Bereich ist für eine spätere Code- oder Graphvorschau reserviert.</p></section></div>{:else}<p>Keine Meldung ausgewählt.</p>{/if}</aside></div>{/if}
</section>{/if}{/if}
<style>
 .diagnostics{position:fixed;z-index:30;left:16px;right:16px;bottom:12px;height:auto;min-height:0;overflow:visible;border:1px solid var(--w-border,#bbb);border-radius:7px;background:var(--w-panel,#fff);box-shadow:0 8px 24px #0003;color:var(--w-text,#222);font:13px system-ui;text-align:left}.diagnostics.open{height:var(--diagnostic-height)}.diagnostics.rail{left:calc(var(--workspace-rail-width,88px) + 12px)}.diagnostics.embedded{position:relative;inset:auto;height:100%;border:0;border-radius:0;box-shadow:none}.rail-trigger{display:inline-flex;align-items:center;justify-content:center;width:34px;height:34px;padding:0;border:1px solid var(--w-danger,var(--w-border,#bbb));border-radius:5px;background:var(--w-panel,#fff);color:var(--w-danger,#b42318);font:700 12px system-ui;cursor:pointer}.resize-handle{position:absolute;top:-7px;left:0;right:0;height:13px;cursor:ns-resize;z-index:2}.embedded .resize-handle{display:none}.summary{width:100%;display:flex;justify-content:space-between;gap:16px;padding:9px 14px;border:0;background:var(--w-panel,#fff);color:inherit;font:inherit;font-weight:600;cursor:pointer;text-align:left}.diagnostics.open .summary{border-bottom:1px solid var(--w-border,#ddd)}.content{height:calc(100% - 40px);display:flex;min-height:0}.rail .content,.embedded .content{height:100%}.table-wrap{flex:1 1 58%;min-width:0;overflow:auto;border-right:1px solid var(--w-border,#ddd)}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{padding:7px 10px;border-bottom:1px solid var(--w-border,#ddd);vertical-align:top;text-align:left}th{position:sticky;top:0;background:var(--w-panel,#fff);font-size:11px;color:var(--w-muted,#666);z-index:1}th:first-child,td:first-child{width:34px;padding-left:8px;padding-right:0}th:nth-child(2),td:nth-child(2){width:100px}th:nth-child(3),td:nth-child(3){width:31%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}td:last-child{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}tr.selected>td{background:color-mix(in srgb,var(--w-info,var(--f-brand,#2563eb)) 10%,var(--w-panel,#fff))}tr[data-severity=error]>td:first-child{border-left:3px solid var(--w-danger,var(--f-danger,#dc2626))}tr[data-severity=warning]>td:first-child{border-left:3px solid var(--w-warning,var(--f-warning,#b45309))}.expand,.details button{font:inherit;color:inherit;background:var(--w-panel,#fff);border:1px solid var(--w-border,#bbb);border-radius:4px;cursor:pointer}.expand{width:24px;height:24px;padding:0}.message{width:100%;overflow:hidden;border:0;padding:0;background:transparent;color:inherit;font:inherit;text-align:left;white-space:nowrap;text-overflow:ellipsis;cursor:pointer}.details{flex:1 1 42%;min-width:280px;display:flex;flex-direction:column;min-height:0;background:var(--w-panel,#fff)}.details header{display:flex;justify-content:space-between;gap:12px;padding:8px 12px;border-bottom:1px solid var(--w-border,#ddd)}.details header span{color:var(--w-muted,#666);font-size:12px}.details-content{overflow:auto;padding:12px}.details h3{margin:0 0 8px;font-size:14px}.details p{margin:7px 0;white-space:pre-wrap;overflow-wrap:anywhere}.details button{padding:5px 8px}.preview-slot{margin-top:16px;padding-top:12px;border-top:1px solid var(--w-border,#ddd);color:var(--w-muted,#666)}.preview-slot p{font-size:12px}.summary:focus-visible,.rail-trigger:focus-visible,.expand:focus-visible,.message:focus-visible,.details button:focus-visible{outline:2px solid var(--w-info,var(--f-brand,#2563eb));outline-offset:-2px}@media(max-width:800px){.diagnostics{left:6px;right:6px;bottom:6px}.diagnostics.rail{left:calc(var(--workspace-rail-width,88px) + 6px)}.content{flex-direction:column}.table-wrap{flex-basis:55%;border-right:0;border-bottom:1px solid var(--w-border,#ddd)}.details{min-width:0;flex-basis:45%}.summary{padding:8px;font-size:12px}th:nth-child(2),td:nth-child(2){width:72px}th:nth-child(3),td:nth-child(3){width:30%}}
</style>
